const SPOTIFY_ARTIST_ID = '1OSLKpjo1NnqzbeI7HEvqI';
 
async function fetchSpotifyTracks() {
  try {
    // Get access token
    const tokenRes = await fetch('https://accounts.spotify.com/api/token', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/x-www-form-urlencoded',
        'Authorization': 'Basic ' + btoa(SPOTIFY_CLIENT_ID + ':' + SPOTIFY_CLIENT_SECRET)
      },
      body: 'grant_type=client_credentials'
    });
    const tokenData = await tokenRes.json();
    const token = tokenData.access_token;
 
    // Get artist top tracks
    const tracksRes = await fetch(
      `https://api.spotify.com/v1/artists/${SPOTIFY_ARTIST_ID}/top-tracks?market=US`,
      { headers: { 'Authorization': 'Bearer ' + token } }
    );
    const tracksData = await tracksRes.json();
    
    if (tracksData.tracks && tracksData.tracks.length > 0) {
      return tracksData.tracks.map(t => ({
        title: t.name.toUpperCase(),
        lang: 'Spotify',
        spotify: t.external_urls.spotify,
        image: t.album.images[0]?.url
      }));
    }
    return null;
  } catch (e) {
    return null;
  }
}
 
